common.base-element.js:
/**
 * BaseLightElement
 * Base class for all Tier 2 Micro-Enhancers.
 * 
 * Enforces key architectural invariants:
 * 1. Zero Shadow DOM: Elements reside in Light-DOM for unbroken a11y trees.
 * 2. Mutate Attributes, Never Nodes: V-DOM safe (React 19, Vue 3, Svelte 5).
 * 3. Lifecycle-safe event listener registration and cleanup.
 */
export class BaseLightElement extends HTMLElement {
  constructor() {
    super();
    this._cleanups = [];
    this._initialized = false;
  }

  /**
   * Forbid attachShadow to enforce unbroken accessibility trees.
   */
  attachShadow() {
    throw new Error(
      `[${this.tagName.toLowerCase()}] Shadow DOM is forbidden in this architecture to preserve native accessibility and form association.`
    );
  }

  connectedCallback() {
    if (!this._initialized) {
      if (this.childElementCount === 0) {
        queueMicrotask(() => {
          if (!this.isConnected || this._initialized) return;
          this.init();
          this._initialized = true;
        });
      } else {
        this.init();
        this._initialized = true;
      }
    }
  }

  disconnectedCallback() {
    this._cleanups.forEach((cleanup) => {
      try {
        cleanup();
      } catch (e) {
        console.error(e);
      }
    });
    this._cleanups = [];
    this._initialized = false;
    this.destroy();
  }

  /**
   * Override in subclasses for initialization logic.
   */
  init() {}

  /**
   * Override in subclasses for teardown logic.
   */
  destroy() {}

  /**
   * Safe event listener that automatically unbinds on disconnectedCallback.
   */
  listen(target, type, listener, options) {
    if (!target) return;
    target.addEventListener(type, listener, options);
    this._cleanups.push(() => {
      target.removeEventListener(type, listener, options);
    });
  }

  /**
   * Standardized native lowercase event dispatcher.
   */
  dispatch(type, detail = {}) {
    const event = new CustomEvent(type, {
      bubbles: true,
      composed: true,
      cancelable: true,
      detail,
    });
    return this.dispatchEvent(event);
  }

  /**
   * Helper to set attribute without triggering unnecessary DOM thrashing.
   */
  setAttributeSafe(node, name, value) {
    if (!node) return;
    if (value === null || value === false) {
      if (node.hasAttribute(name)) node.removeAttribute(name);
    } else {
      const stringVal = value === true ? '' : String(value);
      if (node.getAttribute(name) !== stringVal) {
        node.setAttribute(name, stringVal);
      }
    }
  }

  /**
   * Diagnostic helper to warn developers when AI-generated markup is missing expected parts.
   */
  warnIfMissing(selector, description = '') {
    if (typeof window !== 'undefined' && !this.querySelector(selector)) {
      console.warn(
        `[NNUI-KIT] <${this.tagName.toLowerCase()}>: Missing expected child "${selector}" (${description}). ` +
        `Make sure your template includes this element for proper functionality.`
      );
    }
  }
}

common.a11y.js:
/**
 * Accessibility & APG Keyboard Navigation Utilities
 */

export const Keys = {
  ENTER: 'Enter',
  SPACE: ' ',
  SPACEBAR: 'Spacebar',
  ESCAPE: 'Escape',
  ARROW_DOWN: 'ArrowDown',
  ARROW_UP: 'ArrowUp',
  ARROW_LEFT: 'ArrowLeft',
  ARROW_RIGHT: 'ArrowRight',
  HOME: 'Home',
  END: 'End',
  TAB: 'Tab',
};

let idCounter = 0;
export function generateUniqueId(prefix = 'ui') {
  return `${prefix}-${++idCounter}-${Math.random().toString(36).slice(2, 7)}`;
}

/**
 * Implements WAI-ARIA APG roving tabindex pattern across an array of elements.
 * @param {HTMLElement[]} elements 
 * @param {number} activeIndex 
 * @param {boolean} focusActive 
 */
export function applyRovingTabindex(elements, activeIndex, focusActive = false) {
  elements.forEach((el, index) => {
    if (index === activeIndex) {
      el.setAttribute('tabindex', '0');
      if (focusActive) el.focus();
    } else {
      el.setAttribute('tabindex', '-1');
    }
  });
}

/**
 * Calculates next index for keyboard navigation with wrap-around support.
 */
export function getNextIndex(currentIndex, total, direction, loop = true) {
  if (total === 0) return -1;
  let next = currentIndex + direction;
  if (loop) {
    if (next < 0) next = total - 1;
    if (next >= total) next = 0;
  } else {
    next = Math.max(0, Math.min(total - 1, next));
  }
  return next;
}

common.anchor-fallback.js:
/**
 * Sub-1KB Anchor Positioning Engine & Universal Fallback
 * 
 * Provides rock-solid, cross-browser floating element positioning.
 * Works seamlessly with Native Popover API, top-layer elements, and Light-DOM containers.
 */

export const isAnchorPositioningSupported = (() => {
  if (typeof window === 'undefined' || typeof CSS === 'undefined' || !CSS.supports) {
    return false;
  }
  return (
    (CSS.supports('anchor-name', '--test') && (CSS.supports('position-area', 'bottom span-right') || CSS.supports('inset-area', 'bottom span-right')))
  );
})();

/**
 * Positions a target element relative to an anchor element with viewport-boundary awareness.
 * @param {HTMLElement} anchor 
 * @param {HTMLElement} target 
 * @param {string|object} placement 'bottom' | 'bottom-start' | 'bottom-end' | 'top' | 'left' | 'right' or { placement, offset }
 * @param {number} offset Gap in px (default 6)
 */
export function applyPositionFallback(anchor, target, placement = 'bottom', offset = 6) {
  if (!anchor || !target) return;

  if (typeof placement === 'object' && placement !== null) {
    offset = placement.offset ?? offset;
    placement = placement.placement || 'bottom';
  }

  // Normalize placement strings like 'bottom-start', 'bottom-end', etc.
  let align = 'start';
  let side = 'bottom';
  if (typeof placement === 'string') {
    if (placement.includes('-')) {
      const parts = placement.split('-');
      side = parts[0];
      align = parts[1] || 'start';
    } else {
      side = placement;
      align = 'start';
    }
  }

  const anchorRect = anchor.getBoundingClientRect();
  const targetRect = target.getBoundingClientRect();
  const viewportW = window.innerWidth || (document.documentElement ? document.documentElement.clientWidth : 1200);
  const viewportH = window.innerHeight || (document.documentElement ? document.documentElement.clientHeight : 800);

  // If anchor has zero dimensions (unrendered or detached), attempt parent or skip
  if (anchorRect.width === 0 && anchorRect.height === 0 && anchorRect.top === 0 && anchorRect.left === 0) {
    if (anchor.parentElement && anchor.parentElement.getBoundingClientRect().width > 0) {
      return applyPositionFallback(anchor.parentElement, target, placement, offset);
    }
    return;
  }

  // Determine intrinsic target width without letting unconstrained top-layer popovers stretch to 100vw
  let width = target.offsetWidth || targetRect.width || 280;
  if (width >= viewportW - 20) {
    const firstChild = target.firstElementChild;
    const childW = firstChild ? (firstChild.offsetWidth || firstChild.getBoundingClientRect().width) : 0;
    width = (childW > 0 && childW < viewportW - 20) ? childW : 280;
  }
  if (!width || width <= 0) width = 280;

  let height = target.offsetHeight || targetRect.height || 320;
  if (!height || height <= 0) height = 320;

  let top = 0;
  let left = 0;

  if (side === 'bottom') {
    top = anchorRect.bottom + offset;
    left = align === 'end' ? (anchorRect.right - width) : anchorRect.left;

    // Flip to top ONLY if overflowing bottom AND space above is greater AND it actually fits above
    const spaceBelow = viewportH - (anchorRect.bottom + offset);
    const spaceAbove = anchorRect.top - offset;
    if (top + height > viewportH && spaceAbove > spaceBelow && spaceAbove >= height) {
      top = anchorRect.top - height - offset;
    }
  } else if (side === 'top') {
    top = anchorRect.top - height - offset;
    left = align === 'end' ? (anchorRect.right - width) : anchorRect.left;

    // Flip to bottom if overflowing top and space below exists
    if (top < 0 && anchorRect.bottom + height + offset <= viewportH) {
      top = anchorRect.bottom + offset;
    }
  } else if (side === 'right') {
    top = anchorRect.top;
    left = anchorRect.right + offset;

    if (left + width > viewportW && anchorRect.left - width - offset > 0) {
      left = anchorRect.left - width - offset;
    }
  } else if (side === 'left') {
    top = anchorRect.top;
    left = anchorRect.left - width - offset;

    if (left < 0 && anchorRect.right + width + offset <= viewportW) {
      left = anchorRect.right + offset;
    }
  }

  // Prevent horizontal viewport clipping
  if (left + width > viewportW - 8) {
    left = Math.max(8, viewportW - width - 8);
  }
  if (left < 8) left = 8;

  // Prevent vertical viewport clipping
  if (top + height > viewportH - 8) {
    top = Math.max(8, viewportH - height - 8);
  }
  if (top < 8) top = 8;

  const topPx = `${Math.round(top)}px`;
  const leftPx = `${Math.round(left)}px`;
  const widthPx = `${Math.round(width)}px`;

  // Apply fixed positioning relative to viewport
  if (typeof target.style.setProperty === 'function') {
    target.style.setProperty('position', 'fixed', 'important');
    target.style.setProperty('top', topPx, 'important');
    target.style.setProperty('left', leftPx, 'important');
    target.style.setProperty('right', 'auto', 'important');
    target.style.setProperty('bottom', 'auto', 'important');
    target.style.setProperty('margin', '0', 'important');
    target.style.setProperty('width', widthPx, 'important');
    target.style.setProperty('max-width', 'calc(100vw - 16px)', 'important');
  }

  // Also assign direct properties as fallback for mock DOM environments
  target.style.position = 'fixed';
  target.style.top = topPx;
  target.style.left = leftPx;
  target.style.right = 'auto';
  target.style.bottom = 'auto';
  target.style.margin = '0';
  target.style.width = widthPx;
  target.style.maxWidth = 'calc(100vw - 16px)';
}

common.tokens.css:
@layer ui.tokens {
  :root {
    /* Shadcn Zinc Neutral Color Scale */
    --ui-zinc-50: #fafafa;
    --ui-zinc-100: #f4f4f5;
    --ui-zinc-200: #e4e4e7;
    --ui-zinc-300: #d4d4d8;
    --ui-zinc-400: #a1a1aa;
    --ui-zinc-500: #71717a;
    --ui-zinc-600: #52525b;
    --ui-zinc-700: #3f3f46;
    --ui-zinc-800: #27272a;
    --ui-zinc-900: #18181b;
    --ui-zinc-950: #09090b;

    /* Semantic Accents */
    --ui-color-brand-500: #09090b;
    --ui-color-brand-600: #18181b;
    --ui-color-accent-400: #38bdf8;
    --ui-color-accent-500: #0ea5e9;

    --ui-color-success-500: #10b981;
    --ui-color-warning-500: #f59e0b;
    --ui-color-danger-500: #ef4444;

    /* Semantic Defaults (Light Theme) */
    --ui-bg-canvas: #ffffff;
    --ui-bg-surface: #ffffff;
    --ui-bg-surface-elevated: #f4f4f5;
    --ui-bg-subtle: #f4f4f5;
    --ui-bg-hover: #e4e4e7;
    --ui-bg-active: #d4d4d8;

    --ui-text-primary: #09090b;
    --ui-text-secondary: #52525b;
    --ui-text-muted: #71717a;
    --ui-text-inverted: #fafafa;

    --ui-border-subtle: #f4f4f5;
    --ui-border-default: #e4e4e7;
    --ui-border-strong: #d4d4d8;
    --ui-border-focus: #09090b;

    /* Typography */
    --ui-font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --ui-font-mono: 'JetBrains Mono', 'Fira Code', monospace;
    --ui-font-size-xs: 0.75rem;
    --ui-font-size-sm: 0.875rem;
    --ui-font-size-base: 1rem;
    --ui-font-size-lg: 1.125rem;
    --ui-font-size-xl: 1.25rem;
    --ui-font-size-2xl: 1.5rem;
    --ui-font-size-3xl: 1.875rem;

    /* Spacing */
    --ui-space-1: 0.25rem;
    --ui-space-2: 0.5rem;
    --ui-space-3: 0.75rem;
    --ui-space-4: 1rem;
    --ui-space-5: 1.25rem;
    --ui-space-6: 1.5rem;
    --ui-space-8: 2rem;

    /* Radii */
    --ui-radius-sm: 0.375rem;
    --ui-radius-md: 0.5rem;
    --ui-radius-lg: 0.75rem;
    --ui-radius-xl: 1rem;
    --ui-radius-full: 9999px;

    /* Elevation & Shadows */
    --ui-shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --ui-shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
    --ui-shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.08);
    --ui-shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.12), 0 8px 10px -6px rgba(0, 0, 0, 0.08);
    --ui-shadow-popover: 0 12px 32px -4px rgba(15, 23, 42, 0.18), 0 4px 12px -2px rgba(15, 23, 42, 0.08);

    /* Glassmorphism */
    --ui-glass-bg: rgba(255, 255, 255, 0.82);
    --ui-glass-border: rgba(228, 228, 231, 0.8);
    --ui-glass-blur: blur(12px);

    /* Transitions */
    --ui-transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --ui-transition-base: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Authentic Shadcn Zinc Dark Mode */
  :root[data-theme="dark"],
  [data-theme="dark"] {
    --ui-color-brand-500: #fafafa;
    --ui-color-brand-600: #fafafa;

    --ui-bg-canvas: #09090b;
    --ui-bg-surface: #09090b;
    --ui-bg-surface-elevated: #18181b;
    --ui-bg-subtle: #27272a;
    --ui-bg-hover: #27272a;
    --ui-bg-active: #3f3f46;

    --ui-text-primary: #fafafa;
    --ui-text-secondary: #a1a1aa;
    --ui-text-muted: #71717a;
    --ui-text-inverted: #09090b;

    --ui-border-subtle: #18181b;
    --ui-border-default: #27272a;
    --ui-border-strong: #3f3f46;
    --ui-border-focus: #fafafa;

    --ui-shadow-popover: 0 16px 36px -4px rgba(0, 0, 0, 0.65), 0 4px 16px -2px rgba(0, 0, 0, 0.5);
    --ui-glass-bg: rgba(9, 9, 11, 0.85);
    --ui-glass-border: rgba(39, 39, 42, 0.8);
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --ui-color-brand-500: #fafafa;
      --ui-color-brand-600: #fafafa;

      --ui-bg-canvas: #09090b;
      --ui-bg-surface: #09090b;
      --ui-bg-surface-elevated: #18181b;
      --ui-bg-subtle: #27272a;
      --ui-bg-hover: #27272a;
      --ui-bg-active: #3f3f46;

      --ui-text-primary: #fafafa;
      --ui-text-secondary: #a1a1aa;
      --ui-text-muted: #71717a;
      --ui-text-inverted: #09090b;

      --ui-border-subtle: #18181b;
      --ui-border-default: #27272a;
      --ui-border-strong: #3f3f46;
      --ui-border-focus: #fafafa;

      --ui-shadow-popover: 0 16px 36px -4px rgba(0, 0, 0, 0.65), 0 4px 16px -2px rgba(0, 0, 0, 0.5);
      --ui-glass-bg: rgba(9, 9, 11, 0.85);
      --ui-glass-border: rgba(39, 39, 42, 0.8);
    }
  }
}

common.components.css:
@layer ui.components {
  /* =========================================================================
     Tier 2: Component Styles (Universal Light-DOM Architecture)
     ========================================================================= */

  /* Tabs Component */
  ui-tabs,
  nnui-tabs,
  [data-ui="tabs"] {
    display: flex;
    flex-direction: column;
    width: 100%;

    [data-part="tablist"] {
      display: flex;
      align-items: center;
      gap: var(--ui-space-1);
      border-bottom: 1px solid var(--ui-border-default);
      padding-bottom: 2px;
      margin-bottom: var(--ui-space-4);
      position: relative;
    }

    [data-part="tab"] {
      position: relative;
      padding: 0.5rem 1rem;
      font-size: var(--ui-font-size-sm);
      font-weight: 500;
      color: var(--ui-text-muted);
      background: transparent;
      border: none;
      border-bottom: 2px solid transparent;
      margin-bottom: -3px;
      cursor: pointer;
      transition: color var(--ui-transition-fast), border-color var(--ui-transition-fast);
      user-select: none;
      outline: none;
      border-radius: var(--ui-radius-sm) var(--ui-radius-sm) 0 0;
    }

    [data-part="tab"]:hover {
      color: var(--ui-text-primary);
    }

    [data-part="tab"][aria-selected="true"],
    [data-part="tab"][data-state="active"] {
      color: var(--ui-color-brand-500);
      font-weight: 600;
      border-bottom-color: var(--ui-color-brand-500);
    }

    [data-part="tab"]:focus-visible {
      outline: 2px solid var(--ui-color-brand-400);
      outline-offset: 2px;
    }

    [data-part="tabpanel"] {
      outline: none;
    }

    [data-part="tabpanel"][hidden] {
      display: none !important;
    }
  }

  /* Combobox / Autocomplete Component */
  ui-combobox,
  nnui-combobox,
  [data-ui="combobox"] {
    position: relative;
    display: inline-block;
    width: 100%;

    [data-part="input-wrapper"] {
      position: relative;
      display: flex;
      align-items: center;
    }

    [data-part="input"] {
      width: 100%;
      padding: 0.6rem 2.25rem 0.6rem 0.85rem;
      font-size: var(--ui-font-size-sm);
      border-radius: var(--ui-radius-md);
      border: 1px solid var(--ui-border-default);
      background-color: var(--ui-bg-surface);
      color: var(--ui-text-primary);
      outline: none;
      transition: border-color var(--ui-transition-fast), box-shadow var(--ui-transition-fast);
    }

    [data-part="input"]:focus {
      border-color: var(--ui-color-brand-500);
      box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
    }

    [data-part="toggle-icon"] {
      position: absolute;
      right: 0.75rem;
      pointer-events: none;
      color: var(--ui-text-muted);
      transition: transform var(--ui-transition-fast);
    }

    [aria-expanded="true"] ~ [data-part="toggle-icon"],
    [data-state="open"] [data-part="toggle-icon"] {
      transform: rotate(180deg);
    }

    [data-part="listbox"] {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      max-height: 16rem;
      overflow-y: auto;
      background-color: var(--ui-bg-surface-elevated);
      border: 1px solid var(--ui-border-default);
      border-radius: var(--ui-radius-md);
      box-shadow: var(--ui-shadow-popover);
      padding: var(--ui-space-1);
      margin: 0;
      list-style: none;
      z-index: 50;
      opacity: 0;
      transform: translateY(-4px);
      pointer-events: none;
      transition: opacity var(--ui-transition-fast), transform var(--ui-transition-fast);
    }

    [data-part="listbox"][data-state="open"] {
      opacity: 1;
      transform: translateY(0);
      pointer-events: auto;
    }

    [data-part="option"] {
      padding: 0.5rem 0.75rem;
      border-radius: var(--ui-radius-sm);
      font-size: var(--ui-font-size-sm);
      color: var(--ui-text-primary);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: space-between;
      user-select: none;
      transition: background-color var(--ui-transition-fast);
    }

    [data-part="option"]:hover,
    [data-part="option"][data-focused="true"] {
      background-color: var(--ui-bg-hover);
    }

    [data-part="option"][aria-selected="true"] {
      background-color: rgba(99, 102, 241, 0.12);
      color: var(--ui-color-brand-500);
      font-weight: 500;
    }

    [data-part="empty"] {
      padding: 0.75rem;
      text-align: center;
      font-size: var(--ui-font-size-sm);
      color: var(--ui-text-muted);
    }
  }

  /* Select Component (ElementInternals Form Associated) */
  ui-select,
  nnui-select,
  [data-ui="select"] {
    position: relative;
    display: inline-block;
    width: 100%;

    [data-part="trigger"] {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.6rem 0.85rem;
      font-size: var(--ui-font-size-sm);
      border-radius: var(--ui-radius-md);
      border: 1px solid var(--ui-border-default);
      background-color: var(--ui-bg-surface);
      color: var(--ui-text-primary);
      cursor: pointer;
      text-align: left;
      outline: none;
      transition: border-color var(--ui-transition-fast), box-shadow var(--ui-transition-fast);
    }

    [data-part="trigger"]:focus {
      border-color: var(--ui-color-brand-500);
      box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
    }

    [data-part="listbox"] {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      max-height: 16rem;
      overflow-y: auto;
      background-color: var(--ui-bg-surface-elevated);
      border: 1px solid var(--ui-border-default);
      border-radius: var(--ui-radius-md);
      box-shadow: var(--ui-shadow-popover);
      padding: var(--ui-space-1);
      margin: 0;
      list-style: none;
      z-index: 50;
      display: none;
    }

    [data-part="listbox"][data-state="open"] {
      display: block;
      animation: uiSlideDown 150ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    [data-part="option"] {
      padding: 0.5rem 0.75rem;
      border-radius: var(--ui-radius-sm);
      font-size: var(--ui-font-size-sm);
      color: var(--ui-text-primary);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: space-between;
      transition: background-color var(--ui-transition-fast);
    }

    [data-part="option"]:hover,
    [data-part="option"][data-focused="true"] {
      background-color: var(--ui-bg-hover);
    }

    [data-part="option"][aria-selected="true"] {
      background-color: rgba(99, 102, 241, 0.12);
      color: var(--ui-color-brand-500);
      font-weight: 500;
    }
  }

  /* Accordion Component */
  ui-accordion,
  nnui-accordion,
  [data-ui="accordion"] {
    display: flex;
    flex-direction: column;
    gap: var(--ui-space-2);
    width: 100%;

    [data-part="item"] {
      border: 1px solid var(--ui-border-default);
      border-radius: var(--ui-radius-md);
      background-color: var(--ui-bg-surface);
      overflow: hidden;
      transition: border-color var(--ui-transition-fast);
    }

    [data-part="item"][data-state="open"] {
      border-color: var(--ui-border-strong);
    }

    [data-part="trigger"] {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.85rem 1rem;
      font-size: var(--ui-font-size-sm);
      font-weight: 500;
      color: var(--ui-text-primary);
      background: transparent;
      border: none;
      cursor: pointer;
      text-align: left;
      outline: none;
    }

    [data-part="trigger"]:focus-visible {
      outline: 2px solid var(--ui-color-brand-400);
      outline-offset: -2px;
    }

    [data-part="icon"],
    [data-part="indicator"] {
      transition: transform var(--ui-transition-base);
      color: var(--ui-text-muted);
      display: inline-block;
      font-size: 1.15rem;
      line-height: 1;
    }

    [data-part="item"][data-state="open"] [data-part="icon"],
    [data-part="item"][data-state="open"] [data-part="indicator"] {
      transform: rotate(90deg);
    }

    [data-part="content"] {
      padding: 0 1rem 1rem 1rem;
      color: var(--ui-text-secondary);
      font-size: var(--ui-font-size-sm);
      line-height: 1.5;
      display: none;
    }

    [data-part="item"][data-state="open"] > [data-part="content"],
    [data-state="open"] > [data-part="content"] {
      display: block;
      animation: uiSlideDown 150ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    [data-part="content"][hidden] {
      display: none !important;
    }
  }

  /* Tooltip Component */
  ui-tooltip,
  nnui-tooltip,
  [data-ui="tooltip"] {
    display: inline-flex;
    position: relative;

    [data-part="content"] {
      position: absolute;
      bottom: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%) translateY(4px);
      background-color: var(--ui-bg-surface-elevated);
      color: var(--ui-text-primary);
      border: 1px solid var(--ui-border-default);
      font-size: var(--ui-font-size-xs);
      font-weight: 500;
      padding: 0.35rem 0.65rem;
      border-radius: var(--ui-radius-sm);
      white-space: nowrap;
      pointer-events: none;
      opacity: 0;
      visibility: hidden;
      transition: opacity var(--ui-transition-fast), transform var(--ui-transition-fast), visibility var(--ui-transition-fast);
      box-shadow: var(--ui-shadow-md);
      z-index: 1000;
    }

    &:hover [data-part="content"],
    &:focus-within [data-part="content"],
    &[data-state="visible"] [data-part="content"],
    [data-state="visible"] > [data-part="content"] {
      opacity: 1;
      visibility: visible;
      transform: translateX(-50%) translateY(0);
    }
  }

  /* =========================================================================
     Command Palette Component (<ui-command>, <nnui-command>)
     ========================================================================= */
  ui-command,
  nnui-command,
  [data-ui="command"] {
    display: block;
    width: 100%;
  }

  ui-command dialog[data-part="dialog"],
  nnui-command dialog[data-part="dialog"],
  [data-ui="command"] dialog[data-part="dialog"] {
    padding: 0;
    border: 1px solid var(--ui-border-default);
    border-radius: var(--ui-radius-lg);
    background-color: var(--ui-bg-surface);
    color: var(--ui-text-primary);
    box-shadow: var(--ui-shadow-xl);
    width: 90vw;
    max-width: 640px;
    overflow: hidden;
    animation: ui-command-scale 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  ui-command dialog[data-part="dialog"]::backdrop,
  nnui-command dialog[data-part="dialog"]::backdrop,
  [data-ui="command"] dialog[data-part="dialog"]::backdrop {
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(4px);
    animation: ui-fade-in 150ms ease;
  }

  [data-part="command-wrapper"] {
    display: flex;
    flex-direction: column;
    width: 100%;
    overflow: hidden;
  }

  [data-part="input-wrapper"] {
    display: flex;
    align-items: center;
    gap: var(--ui-space-3);
    padding: 0.85rem 1rem;
    border-bottom: 1px solid var(--ui-border-default);
    background-color: var(--ui-bg-surface);
  }

  [data-part="search-icon"] {
    font-size: 1rem;
    color: var(--ui-text-muted);
    flex-shrink: 0;
  }

  [data-part="input-wrapper"] [data-part="input"] {
    flex: 1;
    background: transparent;
    border: none;
    outline: none;
    font-family: var(--ui-font-sans);
    font-size: var(--ui-font-size-sm);
    color: var(--ui-text-primary);
  }

  [data-part="input-wrapper"] [data-part="input"]::placeholder {
    color: var(--ui-text-muted);
  }

  [data-part="list"] {
    max-height: 320px;
    overflow-y: auto;
    padding: var(--ui-space-2);
  }

  [data-part="group"] {
    margin-bottom: var(--ui-space-2);
  }

  [data-part="group-heading"] {
    font-size: var(--ui-font-size-xs);
    font-weight: 600;
    color: var(--ui-text-muted);
    padding: 0.5rem 0.75rem 0.25rem 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  [data-part="item"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ui-space-2);
    padding: 0.5rem 0.75rem;
    border-radius: var(--ui-radius-md);
    font-size: var(--ui-font-size-sm);
    color: var(--ui-text-primary);
    cursor: pointer;
    user-select: none;
    transition: background-color var(--ui-transition-fast), color var(--ui-transition-fast);
  }

  [data-part="item"][data-active="true"] {
    background-color: var(--ui-bg-hover);
    color: var(--ui-text-primary);
  }

  [data-part="item"][hidden] {
    display: none !important;
  }

  [data-part="empty"] {
    padding: 2.5rem 1rem;
    text-align: center;
    font-size: var(--ui-font-size-sm);
    color: var(--ui-text-muted);
  }

  /* =========================================================================
     Sheet / Drawer Component (<ui-sheet>, <nnui-sheet>)
     ========================================================================= */
  ui-sheet,
  nnui-sheet,
  [data-ui="sheet"] {
    display: inline-block;
  }

  ui-sheet dialog[data-part="dialog"],
  nnui-sheet dialog[data-part="dialog"],
  [data-ui="sheet"] dialog[data-part="dialog"] {
    position: fixed;
    margin: 0;
    border: none;
    background-color: var(--ui-bg-surface);
    color: var(--ui-text-primary);
    box-shadow: var(--ui-shadow-xl);
    overflow-y: auto;
    z-index: 1000;
  }

  ui-sheet dialog[data-part="dialog"]::backdrop,
  nnui-sheet dialog[data-part="dialog"]::backdrop,
  [data-ui="sheet"] dialog[data-part="dialog"]::backdrop {
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(4px);
    animation: ui-fade-in 200ms ease;
  }

  /* Sheet Side: Right (Default) */
  ui-sheet[side="right"] dialog[data-part="dialog"],
  ui-sheet:not([side]) dialog[data-part="dialog"],
  nnui-sheet[side="right"] dialog[data-part="dialog"],
  nnui-sheet:not([side]) dialog[data-part="dialog"] {
    top: 0;
    right: 0;
    bottom: 0;
    left: auto;
    height: 100vh;
    max-height: 100vh;
    width: 100%;
    max-width: 440px;
    border-left: 1px solid var(--ui-border-default);
    animation: ui-sheet-slide-in-right 250ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  ui-sheet[side="right"][data-closing="true"] dialog[data-part="dialog"],
  ui-sheet:not([side])[data-closing="true"] dialog[data-part="dialog"] {
    animation: ui-sheet-slide-out-right 200ms ease forwards;
  }

  /* Sheet Side: Left */
  ui-sheet[side="left"] dialog[data-part="dialog"],
  nnui-sheet[side="left"] dialog[data-part="dialog"] {
    top: 0;
    left: 0;
    bottom: 0;
    right: auto;
    height: 100vh;
    max-height: 100vh;
    width: 100%;
    max-width: 440px;
    border-right: 1px solid var(--ui-border-default);
    animation: ui-sheet-slide-in-left 250ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  ui-sheet[side="left"][data-closing="true"] dialog[data-part="dialog"] {
    animation: ui-sheet-slide-out-left 200ms ease forwards;
  }

  /* Sheet Side: Bottom */
  ui-sheet[side="bottom"] dialog[data-part="dialog"],
  nnui-sheet[side="bottom"] dialog[data-part="dialog"] {
    top: auto;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100vw;
    max-height: 80vh;
    border-top: 1px solid var(--ui-border-default);
    border-radius: var(--ui-radius-lg) var(--ui-radius-lg) 0 0;
    animation: ui-sheet-slide-in-bottom 250ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  ui-sheet[side="bottom"][data-closing="true"] dialog[data-part="dialog"] {
    animation: ui-sheet-slide-out-bottom 200ms ease forwards;
  }

  /* Sheet Content Elements */
  [data-part="sheet-content"] {
    display: flex;
    flex-direction: column;
    height: 100%;
    padding: var(--ui-space-6);
  }

  [data-part="sheet-header"] {
    margin-bottom: var(--ui-space-6);
  }

  [data-part="sheet-title"] {
    font-size: var(--ui-font-size-lg);
    font-weight: 700;
    color: var(--ui-text-primary);
    margin: 0;
  }

  [data-part="sheet-description"] {
    font-size: var(--ui-font-size-sm);
    color: var(--ui-text-muted);
    margin: 0.35rem 0 0 0;
    line-height: 1.45;
  }

  [data-part="sheet-body"] {
    flex: 1;
    overflow-y: auto;
    margin-bottom: var(--ui-space-6);
  }

  [data-part="sheet-footer"] {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--ui-space-3);
    padding-top: var(--ui-space-4);
    border-top: 1px solid var(--ui-border-subtle);
  }

  /* =========================================================================
     Slider Component (<ui-slider>, <nnui-slider>)
     ========================================================================= */
  ui-slider,
  nnui-slider,
  [data-ui="slider"] {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
    height: 1.5rem;
    cursor: pointer;
    user-select: none;
    touch-action: none;
  }

  ui-slider [data-part="track"],
  nnui-slider [data-part="track"],
  [data-ui="slider"] [data-part="track"] {
    position: relative;
    width: 100%;
    height: 0.5rem;
    background-color: var(--ui-bg-subtle);
    border: 1px solid var(--ui-border-default);
    border-radius: var(--ui-radius-full);
    overflow: hidden;
  }

  ui-slider [data-part="range"],
  nnui-slider [data-part="range"],
  [data-ui="slider"] [data-part="range"] {
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    background-color: var(--ui-color-brand-600);
    border-radius: var(--ui-radius-full);
  }

  ui-slider [data-part="thumb"],
  nnui-slider [data-part="thumb"],
  [data-ui="slider"] [data-part="thumb"] {
    position: absolute;
    top: 50%;
    transform: translate(-50%, -50%);
    width: 1.25rem;
    height: 1.25rem;
    border-radius: 50%;
    background-color: var(--ui-bg-surface);
    border: 2px solid var(--ui-color-brand-600);
    box-shadow: var(--ui-shadow-sm);
    outline: none;
    transition: transform var(--ui-transition-fast), box-shadow var(--ui-transition-fast);
  }

  ui-slider [data-part="thumb"]:hover,
  nnui-slider [data-part="thumb"]:hover,
  [data-ui="slider"] [data-part="thumb"]:hover {
    transform: translate(-50%, -50%) scale(1.15);
  }

  ui-slider [data-part="thumb"]:focus-visible,
  nnui-slider [data-part="thumb"]:focus-visible,
  [data-ui="slider"] [data-part="thumb"]:focus-visible {
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.35);
    border-color: var(--ui-border-focus);
  }

  ui-slider[disabled],
  nnui-slider[disabled],
  [data-ui="slider"][disabled] {
    opacity: 0.5;
    cursor: not-allowed;
    pointer-events: none;
  }

  /* Animations */
  @keyframes ui-command-scale {
    from {
      opacity: 0;
      transform: scale(0.96) translateY(-8px);
    }
    to {
      opacity: 1;
      transform: scale(1) translateY(0);
    }
  }

  @keyframes ui-fade-in {
    from { opacity: 0; }
    to { opacity: 1; }
  }

  @keyframes ui-sheet-slide-in-right {
    from { transform: translateX(100%); }
    to { transform: translateX(0); }
  }

  @keyframes ui-sheet-slide-out-right {
    from { transform: translateX(0); }
    to { transform: translateX(100%); }
  }

  @keyframes ui-sheet-slide-in-left {
    from { transform: translateX(-100%); }
    to { transform: translateX(0); }
  }

  @keyframes ui-sheet-slide-out-left {
    from { transform: translateX(0); }
    to { transform: translateX(-100%); }
  }

  @keyframes ui-sheet-slide-in-bottom {
    from { transform: translateY(100%); }
    to { transform: translateY(0); }
  }

  @keyframes ui-sheet-slide-out-bottom {
    from { transform: translateY(0); }
    to { transform: translateY(100%); }
  }

  @keyframes uiSlideDown {
    from {
      opacity: 0;
      transform: translateY(-4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* =========================================================================
     Dropdown Menu Component (<ui-dropdown>, <nnui-dropdown>)
     ========================================================================= */
  ui-dropdown,
  nnui-dropdown,
  [data-ui="dropdown"] {
    position: relative;
    display: inline-block;

    [data-part="menu"] {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      min-width: 13rem;
      background-color: var(--ui-bg-surface-elevated);
      border: 1px solid var(--ui-border-default);
      border-radius: var(--ui-radius-lg);
      box-shadow: var(--ui-shadow-popover);
      padding: var(--ui-space-1);
      margin: 0;
      list-style: none;
      z-index: 1000;
      outline: none;
      display: none;
    }

    [data-part="menu"][data-state="open"] {
      display: block;
      animation: uiSlideDown 150ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    [data-part="item"] {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: var(--ui-space-3);
      padding: 0.5rem 0.75rem;
      border-radius: var(--ui-radius-sm);
      font-size: var(--ui-font-size-sm);
      font-weight: 500;
      color: var(--ui-text-primary);
      background: transparent;
      border: none;
      width: 100%;
      cursor: pointer;
      text-align: left;
      user-select: none;
      outline: none;
      transition: background-color var(--ui-transition-fast), color var(--ui-transition-fast);
    }

    [data-part="item"]:hover,
    [data-part="item"][data-focused="true"] {
      background-color: var(--ui-bg-hover);
      color: var(--ui-text-primary);
    }

    [data-part="item"][data-variant="destructive"] {
      color: var(--ui-color-danger-500);
    }

    [data-part="item"][data-variant="destructive"]:hover,
    [data-part="item"][data-variant="destructive"][data-focused="true"] {
      background-color: rgba(239, 68, 68, 0.12);
      color: var(--ui-color-danger-500);
    }

    [data-part="item"][disabled],
    [data-part="item"][aria-disabled="true"] {
      opacity: 0.45;
      cursor: not-allowed;
      pointer-events: none;
    }

    [data-part="item-main"] {
      display: flex;
      align-items: center;
      gap: var(--ui-space-2);
    }

    [data-part="shortcut"] {
      font-size: var(--ui-font-size-xs);
      font-family: var(--ui-font-mono);
      color: var(--ui-text-muted);
      letter-spacing: 0.05em;
    }

    [data-part="separator"] {
      height: 1px;
      background-color: var(--ui-border-subtle);
      margin: var(--ui-space-1) 0;
    }

    [data-part="label"] {
      padding: 0.35rem 0.75rem 0.2rem;
      font-size: var(--ui-font-size-xs);
      font-weight: 600;
      color: var(--ui-text-muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }
  }

  /* =========================================================================
     Toaster Notification Component (<ui-toaster>, <nnui-toaster>)
     ========================================================================= */
  ui-toaster,
  nnui-toaster,
  [data-ui="toaster"] {
    position: fixed;
    z-index: 9999;
    pointer-events: none;
    display: flex;
    flex-direction: column;
    gap: var(--ui-space-2);
    max-width: 420px;
    width: 100%;
    padding: var(--ui-space-4);

    &[position="bottom-right"],
    &:not([position]) {
      bottom: 0;
      right: 0;
    }

    &[position="top-right"] {
      top: 0;
      right: 0;
    }

    &[position="bottom-left"] {
      bottom: 0;
      left: 0;
    }

    &[position="top-left"] {
      top: 0;
      left: 0;
    }

    &[position="top-center"] {
      top: 0;
      left: 50%;
      transform: translateX(-50%);
    }

    &[position="bottom-center"] {
      bottom: 0;
      left: 50%;
      transform: translateX(-50%);
    }
  }

  [data-ui="toast"] {
    pointer-events: auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ui-space-3);
    padding: 0.85rem 1rem;
    background-color: var(--ui-bg-surface-elevated);
    border: 1px solid var(--ui-border-default);
    border-radius: var(--ui-radius-lg);
    box-shadow: var(--ui-shadow-lg);
    color: var(--ui-text-primary);
    transition: all var(--ui-transition-base);
    animation: uiToastSlideIn 200ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  [data-ui="toast"][data-state="closed"] {
    animation: uiToastSlideOut 180ms ease forwards;
  }

  [data-part="toast-content"] {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-3);
    flex: 1;
  }

  [data-part="toast-icon"] {
    font-size: 1rem;
    font-weight: 700;
    line-height: 1.25;

    &[data-type="success"] { color: var(--ui-color-success-500); }
    &[data-type="error"] { color: var(--ui-color-danger-500); }
    &[data-type="warning"] { color: var(--ui-color-warning-500); }
    &[data-type="info"] { color: var(--ui-color-accent-400); }
  }

  [data-part="toast-text"] {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
  }

  [data-part="toast-title"] {
    font-size: var(--ui-font-size-sm);
    font-weight: 600;
    color: var(--ui-text-primary);
    line-height: 1.35;
  }

  [data-part="toast-description"] {
    font-size: var(--ui-font-size-xs);
    color: var(--ui-text-muted);
    line-height: 1.4;
  }

  [data-part="toast-actions"] {
    display: flex;
    align-items: center;
    gap: var(--ui-space-2);
  }

  [data-part="toast-close"] {
    background: transparent;
    border: none;
    color: var(--ui-text-muted);
    cursor: pointer;
    font-size: 0.85rem;
    padding: 0.25rem;
    border-radius: var(--ui-radius-sm);
    line-height: 1;
    transition: color var(--ui-transition-fast), background-color var(--ui-transition-fast);

    &:hover {
      color: var(--ui-text-primary);
      background-color: var(--ui-bg-hover);
    }
  }

  @keyframes uiToastSlideIn {
    from {
      opacity: 0;
      transform: translateY(12px) scale(0.96);
    }
    to {
      opacity: 1;
      transform: translateY(0) scale(1);
    }
  }

  @keyframes uiToastSlideOut {
    from {
      opacity: 1;
      transform: translateY(0) scale(1);
    }
    to {
      opacity: 0;
      transform: translateY(8px) scale(0.96);
    }
  }

  /* =========================================================================
     Data Table Component (<ui-data-table>, <nnui-data-table>)
     ========================================================================= */
  ui-data-table,
  nnui-data-table,
  [data-ui="data-table"] {
    display: flex;
    flex-direction: column;
    gap: var(--ui-space-3);
    width: 100%;
  }

  ui-data-table [data-part="toolbar"],
  nnui-data-table [data-part="toolbar"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ui-space-4);
    flex-wrap: wrap;
  }

  ui-data-table [data-part="search"],
  nnui-data-table [data-part="search"] {
    max-width: 320px;
    width: 100%;
  }

  ui-data-table [data-part="selection-count"],
  nnui-data-table [data-part="selection-count"] {
    font-size: var(--ui-font-size-xs);
    color: var(--ui-text-muted);
  }

  ui-data-table [data-part="table-container"],
  nnui-data-table [data-part="table-container"] {
    border: 1px solid var(--ui-border-default);
    border-radius: var(--ui-radius-lg);
    overflow: hidden;
    background-color: var(--ui-bg-surface);
  }

  ui-data-table table,
  nnui-data-table table {
    width: 100%;
    border-collapse: collapse;
    font-size: var(--ui-font-size-sm);
    text-align: left;
  }

  ui-data-table th,
  nnui-data-table th {
    padding: 0.75rem 1rem;
    font-weight: 600;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--ui-text-muted);
    background-color: var(--ui-bg-surface-elevated);
    border-bottom: 1px solid var(--ui-border-default);
    white-space: nowrap;
  }

  ui-data-table th[data-sortable="true"],
  nnui-data-table th[data-sortable="true"] {
    cursor: pointer;
    user-select: none;
    transition: color var(--ui-transition-fast), background-color var(--ui-transition-fast);
  }

  ui-data-table th[data-sortable="true"]:hover,
  nnui-data-table th[data-sortable="true"]:hover {
    color: var(--ui-text-primary);
    background-color: var(--ui-bg-subtle);
  }

  ui-data-table [data-part="sort-icon"],
  nnui-data-table [data-part="sort-icon"] {
    display: inline-block;
    margin-left: 0.35rem;
    font-size: 0.7rem;
    opacity: 0.6;
    transition: opacity var(--ui-transition-fast);
  }

  ui-data-table th[aria-sort="ascending"] [data-part="sort-icon"],
