  .ui-date-picker-trigger {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    width: 100%;
    min-width: 220px;
    padding: 0.5rem 0.75rem;
    font-size: var(--ui-font-size-sm);
    font-family: inherit;
    color: var(--ui-text-primary);
    background-color: var(--ui-bg-surface);
    border: 1px solid var(--ui-border-default);
    border-radius: var(--ui-radius-md);
    cursor: pointer;
    transition: all var(--ui-transition-fast);
    user-select: none;
    text-align: left;
    box-sizing: border-box;
  }

  .ui-date-picker-trigger:hover:not([disabled]) {
    border-color: var(--ui-border-strong);
    background-color: var(--ui-bg-hover);
  }

  .ui-date-picker-trigger:focus-visible,
  ui-date-picker[open] .ui-date-picker-trigger {
    outline: 2px solid var(--ui-color-accent-400);
    outline-offset: 1px;
    border-color: var(--ui-color-brand-500);
  }

  .ui-date-picker-trigger[disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .ui-date-picker-icon {
    flex-shrink: 0;
    color: var(--ui-text-muted);
    transition: color var(--ui-transition-fast);
  }

  .ui-date-picker-trigger:hover .ui-date-picker-icon {
    color: var(--ui-text-primary);
  }

  .ui-date-picker-trigger [data-part="display-value"] {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 400;
  }

  ui-date-picker[data-has-value="true"] .ui-date-picker-trigger [data-part="display-value"] {
    font-weight: 500;
    color: var(--ui-text-primary);
  }

  .ui-date-picker-clear-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 2px;
    border-radius: var(--ui-radius-full);
    color: var(--ui-text-muted);
    cursor: pointer;
    transition: all var(--ui-transition-fast);
    margin-right: 2px;
  }

  .ui-date-picker-clear-action:hover {
    color: var(--ui-text-primary);
    background-color: var(--ui-bg-subtle);
  }

  .ui-date-picker-chevron {
    flex-shrink: 0;
    color: var(--ui-text-muted);
    transition: transform var(--ui-transition-fast);
  }

  ui-date-picker[open] .ui-date-picker-chevron {
    transform: rotate(180deg);
  }

  .ui-date-picker-popover {
    position: fixed;
    margin: 0;
    padding: 0;
    width: 280px;
    max-width: 280px;
    min-width: 280px;
    height: auto;
    border: none;
    background: transparent;
    z-index: 9999;
    box-shadow: none;
    overflow: visible;
  }

  .ui-date-picker-popover:not(:popover-open):not([open]) {
    display: none !important;
  }
}

